'use client';
import {useCallback,useEffect,useRef,useState} from 'react';
import {api,send} from '@/lib/client';
import {Button,ErrorBox,SectionHead} from './ui';
interface Status {configured:boolean;botUsername:string;webhookReady:boolean;linked:boolean;telegramId?:number|null}
export function TelegramNotifications(){
 const [status,setStatus]=useState<Status|null>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false),[startUrl,setStartUrl]=useState('');
 const inFlight=useRef(false);
 const refresh=useCallback(async()=>{try{setStatus(await api<Status>('telegram'));setError('');}catch(e){setError((e as Error).message);}},[]);
 useEffect(()=>{void refresh();const onFocus=()=>{void refresh();};window.addEventListener('focus',onFocus);return()=>window.removeEventListener('focus',onFocus);},[refresh]);
 const connect=async()=>{if(inFlight.current)return;inFlight.current=true;setBusy(true);setError('');try{const result=status?.telegramId?{startUrl:`https://t.me/${status.botUsername}`}:await send<{startUrl:string}>('telegram/link',{});if(!/^https:\/\/t\.me\/[A-Za-z0-9_]+(?:\?start=link_[A-Za-z0-9_-]{43})?$/.test(result.startUrl))throw new Error('Invalid Telegram connection link.');setStartUrl(result.startUrl);}catch(e){setError((e as Error).message);}finally{inFlight.current=false;setBusy(false);}};
 const disconnect=async()=>{if(inFlight.current)return;inFlight.current=true;setBusy(true);try{await api('telegram',{method:'DELETE'});setStartUrl('');await refresh();}catch(e){setError((e as Error).message);}finally{inFlight.current=false;setBusy(false);}};
 return <section className="card"><SectionHead title="Telegram notifications"/><p className="muted-text">All Shop Admins use the shared shop_admins bot. Alerts include the shop name and go to the connected owner.</p>{error&&<ErrorBox message={error}/>}<p className="card-footnote">{!status?'Checking connection…':!status.configured?'Head Admin has not configured the Shop Admin bot yet.':status.linked?`Connected to @${status.botUsername}.`:status.webhookReady?status.telegramId?`Use Telegram account ${status.telegramId} and press Start in @${status.botUsername}.`:`Connect @${status.botUsername} to receive order and recharge alerts.`:'Bot setup is still pending.'}</p><div className="form-footer">{status?.linked?<Button disabled={busy} onClick={()=>void disconnect()}>Disconnect Telegram</Button>:<Button disabled={busy||!status?.configured||!status.webhookReady} onClick={()=>void connect()}>{busy?'Preparing…':status?.telegramId?'Open Admin bot':'Connect Telegram'}</Button>}<Button disabled={busy} onClick={()=>void refresh()}>Refresh status</Button></div>{startUrl&&!status?.linked&&<div className="notice"><p><a className="text-link" href={startUrl} target="_blank" rel="noreferrer">Open Telegram and press Start ↗</a><br/>Then return here and refresh the status. {status?.telegramId?'The assigned Telegram account connects when it sends /start.':'This link expires in 10 minutes.'}</p></div>}</section>;
}
