'use client';
import {useEffect,useRef,useState,type ReactNode, type FormEvent} from 'react';
import {X,LoaderCircle,Search,Inbox,ChevronLeft,ChevronRight,Copy,Check,ArrowDownToLine,ArrowUpRight} from 'lucide-react';
import {csv} from '@/lib/client';
import {serverColor} from '@/lib/catalog-table';
import {serverLabel} from '@/lib/shop-catalog';
export function Button({children,onClick,type='button',variant='',disabled=false,className='',title}: {children:ReactNode;onClick?:()=>void;type?:'submit'|'button';variant?:string;disabled?:boolean;className?:string;title?:string}) {return <button title={title} type={type} onClick={onClick} disabled={disabled} className={`btn ${variant} ${className}`}>{children}</button>;}
export function Badge({value}:{value:string|boolean}) {const s=typeof value==='boolean'?(value?'Active':'Disabled'):value;return <span className={`badge ${s.toLowerCase().replaceAll('_','-')}`}>{s.replaceAll('_',' ')}</span>;}
export function Empty({title='Nothing here yet',text='New records will appear here.'}:{title?:string;text?:string}) {return <div className="empty"><span><Inbox size={24}/></span><h3>{title}</h3><p>{text}</p></div>;}
export function Loading(){return <div className="loading" role="status"><LoaderCircle className="spin" size={22}/> Loading your workspace…</div>;}
export function ErrorBox({message,retry}:{message:string;retry?:()=>void}) {return <div className="error-box" role="alert"><p>{message}</p>{retry&&<Button onClick={retry}>Try again</Button>}</div>;}
export function Field({label,children,hint}:{label:string;children:ReactNode;hint?:string}) {return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>;}
export function Modal({title,description,children,onClose,wide=false}:{title:string;description?:string;children:ReactNode;onClose:()=>void;wide?:boolean}) {
 const ref=useRef<HTMLDivElement>(null), closeRef=useRef(onClose);closeRef.current=onClose;
 useEffect(()=>{const old=document.activeElement as HTMLElement|null;const overflow=document.body.style.overflow;document.body.style.overflow='hidden';const el=ref.current;const items=()=>Array.from(el?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href],[tabindex="0"]')??[]);items()[0]?.focus();const key=(e:KeyboardEvent)=>{if(e.key==='Escape')closeRef.current();if(e.key==='Tab'){const a=items(),first=a[0],last=a[a.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};document.addEventListener('keydown',key);return()=>{document.body.style.overflow=overflow;document.removeEventListener('keydown',key);old?.focus();};},[]);
 return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><div role="dialog" aria-modal="true" aria-label={title} className={`modal ${wide?'wide':''}`} ref={ref}><div className="modal-head"><div><h2>{title}</h2>{description&&<p>{description}</p>}</div><button aria-label="Close dialog" className="icon-btn" onClick={onClose}><X size={19}/></button></div>{children}</div></div>;
}
export function Form({onSubmit,children,submit='Save changes',onCancel,danger=false,className=''}:{onSubmit:(data:FormData)=>Promise<void>;children:ReactNode;submit?:string;onCancel?:()=>void;danger?:boolean;className?:string}) {
 const [busy,setBusy]=useState(false),[error,setError]=useState('');
 async function handle(e:FormEvent<HTMLFormElement>){e.preventDefault();if(busy)return;setBusy(true);setError('');const data=new FormData(e.currentTarget);try{await onSubmit(data);}catch(err){setError(err instanceof Error?err.message:'Something went wrong.');}finally{setBusy(false);}}
 return <form className={className} onSubmit={handle}><fieldset disabled={busy} className="form-fields">{children}</fieldset>{error&&<div role="alert" className="form-error">{error}</div>}<div className="form-footer">{onCancel&&<Button disabled={busy} onClick={onCancel}>Cancel</Button>}<Button disabled={busy} type="submit" variant={danger?'danger':'primary'}>{busy?<LoaderCircle size={16} className="spin"/>:null}{busy?'Saving…':submit}</Button></div></form>;
}
export const val=(f:FormData,key:string)=>String(f.get(key)??'').trim();
export function CopyButton({text,label='Copy'}:{text:string;label?:string}){const [done,setDone]=useState(false),[error,setError]=useState(false);return <Button onClick={async()=>{try{await navigator.clipboard.writeText(text);setDone(true);setError(false);setTimeout(()=>setDone(false),2000);}catch{setError(true);}}}>{done?<Check size={14}/>:<Copy size={14}/>} {error?'Select and copy manually':done?'Copied':label}</Button>;}
export function SearchBox({value,onChange,placeholder='Search records…'}:{value:string;onChange:(v:string)=>void;placeholder?:string}) {return <div className="search-box"><Search size={16}/><input aria-label={placeholder} placeholder={placeholder} value={value} onChange={e=>onChange(e.target.value)}/>{value&&<button className="icon-btn" aria-label="Clear search" onClick={()=>onChange('')}><X size={14}/></button>}</div>;}
export function Pager({page,totalPages,total,onChange}:{page:number;totalPages:number;total:number;onChange:(p:number)=>void}){return <div className="pager"><span>{total.toLocaleString()} total records · Page {page+1} of {Math.max(1,totalPages)}</span><div><Button disabled={page===0} onClick={()=>onChange(page-1)} title="Previous page"><ChevronLeft size={16}/></Button><Button disabled={page+1>=totalPages} onClick={()=>onChange(page+1)} title="Next page"><ChevronRight size={16}/></Button></div></div>;}
export function SectionHead({title,sub,action}:{title:string;sub?:string;action?:ReactNode}) {return <div className="section-head"><div><h2>{title}</h2>{sub&&<p>{sub}</p>}</div>{action}</div>;}
export function Export({name,rows}:{name:string;rows:Record<string,unknown>[]}){return <Button disabled={!rows.length} onClick={()=>csv(name,rows)}><ArrowDownToLine size={15}/> Export CSV</Button>;}
export function Stat({label,value,sub,icon}:{label:string;value:ReactNode;sub:string;icon:ReactNode}){return <div className="stat"><div className="stat-top"><span>{label}</span><span className="stat-icon">{icon}</span></div><strong>{value}</strong><small>{sub}</small></div>;}
export function Detail({label,children}:{label:string;children:ReactNode}){return <div className="detail-item"><dt>{label}</dt><dd>{children??'—'}</dd></div>;}
export function External({href,children}:{href:string;children:ReactNode}){return <a className="text-link" href={href} target="_blank" rel="noreferrer">{children}<ArrowUpRight size={14}/></a>;}

export function ServerBadge({id,label}:{id?:string;label?:string}){const name=serverLabel({providerId:id,serverName:label});return <span className="server-badge"><i style={{backgroundColor:serverColor(id||name)}} aria-hidden="true"/>{name}</span>;}
